/// Whether the program states the exit code `code`.
///
/// This is the question [`explain_ec`] answers with an empty string, asked on its own: a
/// caller that has to tell "no such code" from "a code with nothing said about it" asks
/// this rather than reading the string, since a code the program states always has a key
/// with something under it.
#[must_use]
pub fn has_ec(code: i32) -> bool {
    CODES.contains(&code)
}

/// What the exit code `code` means, in the words `i18n/exit_codes.yml` holds for the key it
